/* Narrative reports are generated by explicit local rules; no AI service is called. */
(function(){
'use strict';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ko=gz=>Array.from(gz).map(c=>Saju.KO[c]).join('');
window.mountInsights=function(r){
 const forecast=Saju.forecast(r,r.input.gender);let selected='love',cycle=forecast.daeun?.cycles.findIndex(c=>c.current)??-1;if(cycle<0)cycle=0;
 const section=document.createElement('section');section.className='insights';section.setAttribute('aria-labelledby','insights-heading');
 section.innerHTML=`<div class="insights-heading"><div><span class="eyebrow">YOUR OWN STORY, IN DEPTH</span><h2 id="insights-heading">여덟 글자 너머, 당신의 이야기.</h2></div><span class="insights-flower" aria-hidden="true">✳</span></div><div class="insight-tabs" role="tablist" aria-label="사주 해설 주제">${[['personality','나의 성격','✧'],['love','연애 상담·연애운','♡'],['daeun','대운 타임라인','⌁'],['annual','올해·내년 운세','◷']].map(([id,label,icon])=>`<button id="tab-${id}" role="tab" aria-controls="insight-${id}" aria-selected="${id===selected}" tabindex="${id===selected?0:-1}" data-tab="${id}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div>${['personality','love','daeun','annual'].map(id=>`<div id="insight-${id}" role="tabpanel" aria-labelledby="tab-${id}" ${id===selected?'':'hidden'}></div>`).join('')}<p class="report-footnote">전통 명리학의 상징을 조합한 규칙 기반 해설입니다. AI 생성 상담이나 사건 예측은 아니며, 실제 성격과 관계는 경험·환경·선택에 따라 달라집니다.</p>`;
 document.querySelector('#result-content .result-grid').before(section);
 const chapters=report=>`<div class="report-chapters">${report.chapters.map((c,i)=>`<section class="report-chapter"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><div><h4>${safe(c.title)}</h4>${c.paragraphs.map(p=>`<p>${safe(p)}</p>`).join('')}</div></section>`).join('')}</div>`;
 const report=(data,label)=>`<article class="panel long-report"><div class="report-cover"><span class="reading-label">${label}</span><h3>${safe(data.title)}</h3><p class="report-opening">${safe(data.lead)}</p></div>${chapters(data)}</article>`;
 function daeun(data){const d=forecast.daeun;if(!d)return `<article class="panel empty-daeun"><span class="reading-label">TEN YEARS, ONE CHAPTER</span><h3>대운을 포함한 이야기를 읽으려면</h3><p>입력 화면에서 전통 대운 계산 기준을 선택해주세요. 순행·역행과 시작 시각을 계산한 뒤, 원국과 함께 각 구간의 흐름을 풀어드릴게요.</p><a class="button primary" href="#form">대운 계산 기준 선택 <span>→</span></a></article>`;
 return `<article class="panel daeun-panel long-report"><div class="panel-title-row"><div><span class="reading-label">TEN YEARS, ONE CHAPTER</span><h3>열 해마다 펼쳐지는 새로운 장.</h3></div><span class="local-badge">${d.forward?'순행 →':'← 역행'}${d.approximate?' · 시간 미상 참고값':''}</span></div><p class="insight-lead">첫 대운은 출생 후 ${d.years}년 ${d.months}개월 ${d.days}일 ${d.hours}시간에 시작합니다. 구간을 누르면 원국과 함께 읽은 이야기가 이어져요.</p>${d.beforeStart?'<p class="soft-callout">지금은 첫 대운이 시작되기 전입니다.</p>':d.afterEnd?'<p class="soft-callout">현재 시점은 표시된 9개 대운 구간 이후입니다.</p>':''}<div class="daeun-timeline" role="group" aria-label="대운 구간 선택">${d.cycles.map((c,i)=>`<button class="cycle ${cycle===i?'selected':''} ${c.current?'current':''}" data-cycle="${i}" aria-pressed="${cycle===i}" aria-label="${c.start} 시작 ${ko(c.gan+c.zhi)} 대운${c.current?', 현재 구간':''}"><span class="cycle-current">${c.current?'지금의 대운':'만 '+c.age+'세 시작'}</span><strong>${ko(c.gan+c.zhi)}</strong><span class="cycle-han">${c.gan}${c.zhi}</span><span>${c.start.slice(0,4)}–${c.end.slice(0,4)}</span></button>`).join('')}</div><div class="cycle-detail report-cover" aria-live="polite"><span class="small-label">${data.start} ~ ${data.end} 직전 · ${data.current?'현재 구간':'선택한 구간'}</span><h4>${safe(data.title)}</h4><p>${safe(data.lead)}</p></div>${chapters(data)}${d.approximate?'<p class="notice">시간 미상으로 정오를 기준 삼은 시작일입니다. 출생 시간이 확인되면 전환일도 달라질 수 있습니다.</p>':''}</article>`;}
 function annual(reports){return `<div class="annual-report-intro"><span class="eyebrow">THIS YEAR & THE NEXT</span><h3>올해에서 내년으로,<br>무엇을 이어가고 달리 볼까요?</h3><p>${forecast.year}년과 ${forecast.year+1}년을 각각 풀어드려요. 해의 흐름은 입춘부터 다음 입춘까지로 읽습니다.</p></div>${reports.map((a,i)=>`<article class="panel long-report annual-long"><div class="report-cover"><span class="reading-label">${i?'NEXT YEAR':'THIS YEAR'} · ${a.year} ${ko(a.gan+a.zhi)}(${a.gan}${a.zhi})</span><h3>${safe(a.title)}</h3><p class="report-opening">${safe(a.lead)}</p></div>${chapters(a)}</article>`).join('')}`;}
 function render(){const data=SajuReport.build(r,forecast,cycle);const html={personality:()=>report(data.personality,'PERSONALITY · '+Saju.KO[r.dayGan]+r.dayGan),love:()=>report(data.love,'LOVE · YOUR RELATIONSHIP STORY'),daeun:()=>daeun(data.daeun),annual:()=>annual(data.annual)};for(const id of Object.keys(html)){const panel=section.querySelector('#insight-'+id);panel.hidden=id!==selected;if(id===selected)panel.innerHTML=html[id]();}section.querySelectorAll('[role=tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===selected));b.tabIndex=b.dataset.tab===selected?0:-1;});}
 section.addEventListener('click',event=>{const tab=event.target.closest('[data-tab]');if(tab){selected=tab.dataset.tab;render();return;}const c=event.target.closest('[data-cycle]');if(c){const scroll=section.querySelector('.daeun-timeline').scrollLeft;cycle=Number(c.dataset.cycle);render();section.querySelector('.daeun-timeline').scrollLeft=scroll;section.querySelector(`[data-cycle="${cycle}"]`).focus({preventScroll:true});}});
 section.querySelector('[role=tablist]').addEventListener('keydown',event=>{const tabs=[...section.querySelectorAll('[role=tab]')],idx=tabs.indexOf(event.target);if(idx<0)return;let next;if(event.key==='ArrowRight')next=(idx+1)%tabs.length;else if(event.key==='ArrowLeft')next=(idx+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selected=tabs[next].dataset.tab;render();tabs[next].focus();});render();
};
})();
